WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_r_speed'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '速度比', 'kp-trv-r-speed', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "速度比例"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定理：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "当时间相同时，路程之比等于速度之比；当路程相同时，时间之比等于速度的反比。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不给任何速度真实值，全程用“甲的速度是乙的 1.5 倍”或者“甲提速后时间缩短了”的表述。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[遇到纯比例题, 直接将速度比赋值为真实的 V值] --> B[如果题目说提速 x%, 直接写出 V旧:V新 的整数比]\nB --> C[配合路程或时间的恒定关系, 将速度比转换为对应的比例]\nC --> D[找到差距份数, 对应真实差距]"}}]}$$ AS jsonb), NULL, '速度比的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "速度比"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_r_speed", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
